432	fn grows(n: &str, v: &Expr) -> bool {
433	    match v {
434	        Expr::Binary("*", a, b) => matches!(a.as_ref(), Expr::Ident(m) | Expr::Move(m) if m == n) || matches!(b.as_ref(), Expr::Ident(m) | Expr::Move(m) if m == n) || grows(n, a) || grows(n, b),
