207	fn subject_into_stmt(st: &mut Stmt, n: &str, call: &mut Option<Expr>) {
208	    match st {
209	        Stmt::Let { value, .. } | Stmt::Assign { value, .. } => subject_into(value, n, call),
210	        Stmt::Expr { expr, .. } => subject_into(expr, n, call),
