215	fn subject_into(e: &mut Expr, n: &str, call: &mut Option<Expr>) {
216	    if call.is_none() {
217	        return;
218	    }
219	    match e {
220	        Expr::Match(subj, arms) => {
221	            if matches!(subj.as_ref(), Expr::Ident(m) | Expr::Move(m) if m == n) {
222	                **subj = call.take().unwrap();
223	                return;
224	            }
225	            arms.iter_mut().for_each(|(_, b)| subject_into(b, n, call));
226	        }
227	        Expr::Block(st, t) => {
228	            st.iter_mut().for_each(|s| subject_into_stmt(s, n, call));
229	            if let Some(t) = t {
230	                subject_into(t, n, call);
