244	// `?` is optional on calls: a call to a function that can fail passes its error up unless it is
245	// already handled (`?`, `.or(...)`, or a match on Ok/Err). Repeats until no more functions become fallible.
246	pub fn auto_try(items: &mut [Item]) {
247	    loop {
248	        let mut fallible: HashSet<String> = FALLIBLE_BUILTINS.iter().map(|s| s.to_string()).collect();
249	        for it in items.iter() {
250	            if let Item::Fn { name, fallible: f, body, .. } = it {
251	                if *f || can_fail(body) {
252	                    fallible.insert(name.clone());
253	                }
254	            }
255	        }
256	        let before = fallible.len();
257	        for it in items.iter_mut() {
258	            match it {
259	                Item::Fn { body, .. } | Item::Test { body, .. } => wrap_calls(body, &fallible),
260	                _ => {}
261	            }
262	        }
263	        // Counted as a set like `fallible`, so a function defined twice cannot keep the loop going.
264	        let mut now = fallible.clone();
265	        for it in items.iter() {
266	            if let Item::Fn { name, fallible: f, body, .. } = it {
267	                if *f || can_fail(body) {
268	                    now.insert(name.clone());
269	                }
270	            }
271	        }
272	        if now.len() <= before {
273	            return;
274	        }
275	    }
276	}
