```
fn big_parse_base(digits: &str, base: u32) -> Big {
    let mut mag: Vec<u32> = vec![0];
    for c in digits.chars() {
        let d = c.to_digit(base).unwrap();
        let mut carry = d as u64;
        for w in mag.iter_mut() {
            let x = *w as u64 * base as u64 + carry;
            *w = (x % BIG_BASE) as u32;
            carry = x / BIG_BASE;
        }
        while carry > 0 { mag.push((carry % BIG_BASE) as u32); carry /= BIG_BASE; }
    }
    Big::make(false, mag)
}
```
